effect.shader:
float hash11(float p)
{
p = fract(p * 0.1031);
p *= p + 33.33;
p *= p + p;
return fract(p);
}
float hash12(vec2 p)
{
vec3 p3 = fract(vec3(p.xyx) * 0.1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
mat2 rotate2d(float theta)
{
float c = cos(theta);
float s = sin(theta);
return mat2(c, -s, s, c);
}
float noise2(vec2 p)
{
vec2 ip = floor(p);
vec2 fp = fract(p);
float a = hash12(ip);
float b = hash12(ip + vec2(1.0, 0.0));
float c = hash12(ip + vec2(0.0, 1.0));
float d = hash12(ip + vec2(1.0, 1.0));
vec2 t = smoothstep(0.0, 1.0, fp);
return mix(mix(a, b, t.x), mix(c, d, t.x), t.y);
}
float fbm(vec2 p, int octaveCount, float rotAngle)
{
float value = 0.0;
float amplitude = 0.5;
mat2 R = rotate2d(rotAngle);
for (int i = 0; i < 12; ++i)
{
if(i >= octaveCount) break;
value += amplitude * noise2(p);
p = R * p * 2.0;
amplitude *= 0.5;
}
return value;
}
void imagePass(out vec4 fragColor, vec2 fragCoord)
{
vec2 iResolution = acScreenSize;
vec2 uv = fragCoord / iResolution.xy;
uv = 2.0 * uv - 1.0;
uv.x *= iResolution.x / iResolution.y;
float t = acTime * speed;
int   oct = int(octaves + 0.5);
float wobble = fbm(uv + t, oct, rotate);
uv += warp * (wobble - 0.5) * 2.0;
float dist = max(1e-4, abs(uv.x));
vec3 baseCol = vec3(colorR, colorG, colorB);
float jitter = mix(0.0, intensity, hash11(acTime));
float glow = pow(jitter * width / dist, 1.0);
vec3 col = baseCol * glow;
fragColor = vec4(col, 1.0);
}
void main(){
vec2 fragCoord = acScreenNorm * acScreenSize;
vec4 c; imagePass(c, fragCoord); gl_FragColor = c; return;
}
